good_examples.code:
pub(crate) fn internal_update_state(&mut self, account_id: &AccountId, value: u128) {
    // Cannot be called externally - compile-time protection
    self.state.insert(account_id, &value);
}

pub(crate) fn format_helper(&mut self, data: &[u8]) -> Vec<u8> {
    // Cannot be called externally - compile-time protection
    self.process_data(data)
}

#[private]
pub fn format_helper(&mut self, data: &[u8]) -> Vec<u8> {
    // Protected with #[private] - only contract can call
    // Use this if the method needs to be a callback
    self.process_data(data)
}

#[private]
pub fn callback_on_complete(&mut self, result: Result<(), String>) {
    // Only the contract can call this after the cross-contract call
    match result {
        Ok(_) => {
            self.commit_operation();
        }
        Err(_) => {
            // Rollback state and refund user
            Promise::new(self.pending_user.clone()).transfer(self.pending_amount);
        }
    }
}

#[private]
pub fn on_operation_done(&mut self, result: Result<u128, String>) {
    // Protected - only contract can call
    if let Ok(value) = result {
        self.update_value(value);
    }
}

#[private]
pub fn after_operation(&mut self, success: bool) {
    // Protected - only contract can call
    if success {
        self.commit();
    } else {
        self.rollback();
    }
}

pub(crate) fn internal_calculate(&self, amount: u128) -> u128 {
    // Cannot be called externally - compile-time protection
    amount * self.rate / 10000
}

pub(crate) fn calculate_helper(&self, amount: u128) -> u128 {
    // Cannot be called externally - compile-time protection
    amount * self.rate / 10000
}

#[private]
pub fn callback_handler(&mut self, result: Result<(), String>) {
    // Correctly declared as pub fn with #[private] for callbacks
    match result {
        Ok(_) => self.commit_state(),
        Err(_) => self.rollback_state(),
    }
}

// This impl block is NOT decorated - methods are NOT public
impl Contract {
    pub fn internal_helper(&self) -> u128 {
        // ✅ SAFE - Cannot be called externally
        // Not in #[near] impl block
        self.calculate_value()
    }

    pub fn helper_calculate(&self, amount: u128) -> u128 {
        // ✅ SAFE - Cannot be called externally
        // Not in #[near] impl block
        amount * 2
    }
}

// This impl block IS decorated - methods ARE public
#[near]
impl Contract {
    pub fn public_method(&self) {
        // This CAN be called externally
    }
}
